import{G as e,K as t,at as n,n as r}from"./chunks/framework.CZI4dhmU.js";var i=JSON.parse(`{"title":"kubernetes","description":"","frontmatter":{},"headers":[],"relativePath":"middleware/kubernetes/basic/index.md","filePath":"middleware/kubernetes/basic/index.md"}`),a={name:`middleware/kubernetes/basic/index.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="kubernetes" tabindex="-1">kubernetes <a class="header-anchor" href="#kubernetes" aria-label="Permalink to “kubernetes”">​</a></h1><ul><li>官方文档：<a href="https://kubernetes.io/zh-cn/" target="_blank" rel="noreferrer">https://kubernetes.io/zh-cn/</a></li></ul><h2 id="了解k8s" tabindex="-1">了解k8s <a class="header-anchor" href="#了解k8s" aria-label="Permalink to “了解k8s”">​</a></h2><ul><li>视频了解：<a href="https://www.bilibili.com/video/BV1jrdoYqEAc?spm_id_from=333.788.videopod.episodes&amp;vd_source=ad7a7015d055e3611329c5a5f9a00794" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1jrdoYqEAc?spm_id_from=333.788.videopod.episodes&amp;vd_source=ad7a7015d055e3611329c5a5f9a00794</a></li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h2><h3 id="自动化上线和回滚" tabindex="-1">自动化上线和回滚 <a class="header-anchor" href="#自动化上线和回滚" aria-label="Permalink to “自动化上线和回滚”">​</a></h3><ul><li>Kubernetes 会分步骤地将针对应用或其配置的更改上线， 同时监视应用程序运行状况以确保你不会同时终止所有实例。</li><li>如果出现问题，Kubernetes 会为你回滚所作更改。你应该充分利用不断成长的部署方案生态系统。</li></ul><h3 id="服务发现与负载均衡" tabindex="-1">服务发现与负载均衡 <a class="header-anchor" href="#服务发现与负载均衡" aria-label="Permalink to “服务发现与负载均衡”">​</a></h3><ul><li>你无需修改应用来使用陌生的服务发现机制。</li><li>Kubernetes 为每个 Pod 提供了自己的 IP 地址并为一组 Pod 提供一个 DNS 名称，并且可以在它们之间实现负载均衡。</li></ul><h3 id="存储编排" tabindex="-1">存储编排 <a class="header-anchor" href="#存储编排" aria-label="Permalink to “存储编排”">​</a></h3><ul><li>自动挂载所选存储系统，包括本地存储、公有云提供商所提供的存储或者诸如 iSCSI 或 NFS 这类网络存储系统。</li></ul><h3 id="secret-和配置管理" tabindex="-1">Secret 和配置管理 <a class="header-anchor" href="#secret-和配置管理" aria-label="Permalink to “Secret 和配置管理”">​</a></h3><ul><li>部署和更新 Secret 和应用程序的配置而不必重新构建容器镜像， 且不必将软件堆栈配置中的秘密信息暴露出来。</li></ul><h3 id="自动装箱" tabindex="-1">自动装箱 <a class="header-anchor" href="#自动装箱" aria-label="Permalink to “自动装箱”">​</a></h3><ul><li>根据资源需求和其他限制自动放置容器，同时避免影响可用性。</li><li>将关键性的和尽力而为性质的工作负载进行混合放置，以提高资源利用率并节省更多资源。</li></ul><h3 id="批量执行" tabindex="-1">批量执行 <a class="header-anchor" href="#批量执行" aria-label="Permalink to “批量执行”">​</a></h3><ul><li>除了服务之外，Kubernetes 还可以管理你的批处理和 CI 工作负载，在期望时替换掉失效的容器。</li></ul><h3 id="自我修复" tabindex="-1">自我修复 <a class="header-anchor" href="#自我修复" aria-label="Permalink to “自我修复”">​</a></h3><ul><li>Kubernetes 会自动重启崩溃的容器，在必要时替换整个 Pod， 在发生更大范围的故障时重新挂载存储， 并且能够与节点自动扩缩容器集成，实现节点级别的自我修复能力。</li></ul><h3 id="水平扩缩" tabindex="-1">水平扩缩 <a class="header-anchor" href="#水平扩缩" aria-label="Permalink to “水平扩缩”">​</a></h3><ul><li>使用一个简单的命令、一个 UI 或基于 CPU 使用情况自动对应用程序进行扩缩。</li></ul><h3 id="ipv4-ipv6-双协议栈" tabindex="-1">IPv4/IPv6 双协议栈 <a class="header-anchor" href="#ipv4-ipv6-双协议栈" aria-label="Permalink to “IPv4/IPv6 双协议栈”">​</a></h3><ul><li>为 Pod 和 Service 分配 IPv4 和 IPv6 地址</li></ul><h3 id="为扩展性设计" tabindex="-1">为扩展性设计 <a class="header-anchor" href="#为扩展性设计" aria-label="Permalink to “为扩展性设计”">​</a></h3><ul><li>无需更改上游源码即可扩展你的 Kubernetes 集群。</li></ul>`,25)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};